describe('Billing Address Change during Checkout', () => {
    beforeEach(() => {
        cy.visit('/checkout');
        cy.get('#login').type('user@example.com');
        cy.get('#password').type('password123');
        cy.get('#login-button').click();
    });

    it('should successfully change the billing address during checkout', () => {
        cy.get('#billing-address-toggle').click();
        cy.get('#billing-address-street').clear().type('123 New Street');
        cy.get('#billing-address-city').clear().type('New City');
        cy.get('#billing-address-state').select('New State');
        cy.get('#billing-address-zip').clear().type('12345');
        cy.get('#save-billing-address').click();

        cy.get('.success-message').should('contain', 'Billing address updated successfully');
        cy.get('#billing-address-display').should('contain', '123 New Street');
    });

    it('should show an error when the billing address is incomplete', () => {
        cy.get('#billing-address-toggle').click();
        cy.get('#billing-address-street').clear();
        cy.get('#billing-address-city').clear();
        cy.get('#billing-address-state').select('Select State');
        cy.get('#billing-address-zip').clear();
        cy.get('#save-billing-address').click();

        cy.get('.error-message').should('contain', 'Please fill out all required fields');
    });
});
